import { after, connection } from 'next/server'
import { logPageView } from './lib/analytics'

export default async function Home() {
  // Opt into dynamic rendering so the page view is logged per request,
  // not once at build time during prerendering.
  await connection()

  // Runs after the response has finished streaming to the client,
  // so the analytics call never delays rendering.
  after(async () => {
    await logPageView('/')
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting — enjoy your stay!</p>
    </main>
  )
}

